INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('accessible-circulation-geometry', 'RAMP-CO1-IN', 'REF-01006', NULL, 1, 0, '[]', '[backward 2026-09-20 03:25] PASS RAN ON ADMISSION, against the publisher''s Crossref deposit (28 references, reference-count field agrees). DERIVE THE YIELD: python3 scripts/research/mining_screen.py --ref REF-01006 --compare. slope-strict 0, slope-strict-plus-motion 0, slope-loose 7. A ZERO UNDER slope-strict IS CORRECT AND IS NOT A THIN RESULT: this is a health-systems accessibility paper and not one of its references is titled for a geometric quantity. THE CONTRAST WITH REF-01005 IS THE USEFUL PART, and it corrects the reasoning behind a prediction this batch got wrong. P1c predicted slope-loose would score at least 3x slope-strict on REF-01005 because the bare stem accessib would fire on everything in an accessibility report. It did not -- REF-01005''s bibliography is ERGONOMICS (Damon, Diffrient, Kroemer, McCormick, Murrell, Poulton) and accessib barely appears. Here it fires 7 of 28, because THIS anchor''s references really are an accessibility literature. The screen''s behaviour tracks the literature an anchor cites, not the subject of the anchor itself, and that is worth knowing before anyone calibrates a floor on slope-loose again. WHAT THE PASS ACTUALLY FOUND, which no screen in the registry can see: a cluster of at least five ACCESSIBILITY AUDIT studies of real health facilities -- Pinto 2021 (Brazil, national, doi 10.3390/ijerph18062953), Singh 2024 (New Delhi hospitals, doi 10.32388/M7E7KE.3), Garg 2024 (doi 10.1016/j.mjafi.2022.10.011), Sharma 2025 (Gwalior), Mohapatra 2024 (Delphi, doi 10.12688/f1000research.156920.1). Every one of them scores ZERO under slope-strict, and an audit is exactly the document type that tabulates a measured gradient while naming no geometry in its title. Candidates 123 and 124 stage the two strongest. THIS IS THE SAME FALSE-NEGATIVE SHAPE the REF-01005 pass recorded for Walter, arriving from the opposite direction: there a slope study was invisible because its slope was in a part title; here they are invisible because the slope is in a results table. FORWARD PASS NOT RUN: REF-01006 was published in 2026 and admitted the day this batch read it, so a forward graph over it would be empty by construction rather than by omission.', '2026-09-20 03:25', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:25', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', NULL);

