INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id") VALUES (123, 91, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Garg et al. (2024) — Accessibility audit of a health care institute in India: are people with disabilities being provided their rights? (Med J Armed Forces India 80(3):353)', 'doi:10.1016/j.mjafi.2022.10.011 — deposited reference bb0105 in REF-01006''s Crossref record, doi-asserted-by crossref. R9 PRE-CHECKED: not already filed under any ref_id.', 'RESOLVED', 3, 1, 'NOT RETRIEVED THIS BATCH. Surfaced by the REF-01006 backward pass and left for a pass that can read it. It scores ZERO under slope-strict -- its title names no geometric quantity -- so on a title screen it is invisible, and that is precisely the false negative the REF-01005 pass warned about: an accessibility AUDIT is exactly the document type that measures ramp gradients in a table while saying nothing about slope in its title.', 'harm_finding=1: the title poses its own question as whether disabled people are being DENIED rights, so it is an inadequacy study by construction, and R7 makes that first-class evidence rather than a by-product. WHY THIS CLUSTER MATTERS MORE THAN ANY SINGLE ITEM: REF-01006''s reference list contains at least five accessibility-audit studies of Indian and Brazilian health facilities (bb0030 Pinto 2021 Brazil national audit doi 10.3390/ijerph18062953; bb0100 Singh 2024 New Delhi hospitals doi 10.32388/M7E7KE.3; this one; bb0110 Sharma 2025 Gwalior; bb0130 Mohapatra 2024 Delphi on public buildings doi 10.12688/f1000research.156920.1). If any of them tabulates measured gradients, the corpus gains something it has almost none of: what ramps in the world ACTUALLY measure, as against what codes require or what laboratory studies test.', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:24', NULL);
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id") VALUES (124, 91, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Pinto et al. (2021) — A national accessibility audit of primary health care facilities in Brazil: are people with disabilities being denied their right to health? (Int J Environ Res Public Health 18(6):2953)', 'doi:10.3390/ijerph18062953 — deposited reference bb0030 in REF-01006''s Crossref record. MDPI, so gold open access and retrievable; batch 15 established the MDPI CDN route after www.mdpi.com refused a DOI. R9 PRE-CHECKED: not already filed.', 'RESOLVED', 2, 1, 'NOT RETRIEVED THIS BATCH. Staged as the highest-value item in this cluster and the reason is SCALE and JURISDICTION: a NATIONAL audit of primary health care facilities is a far larger measured sample of real built environments than anything this corpus holds, and Brazil is a jurisdiction absent from it entirely. tier_guess 2 rather than 3 because a national facility audit is closer to systematic evidence than to grey primary, but the ladder derives the tier from (evidence_type, scope) on admission and this guess does not bind it.', 'harm_finding=1 on the same reading as its sibling -- the title asks whether people are being DENIED a right. RETRIEVAL IS CHEAP AND THE ROUTE IS KNOWN, which is what separates this cluster from everything else this batch chased: Walter 1971, Elmer 1957 and Templer are all behind GAP-041''s closed catalogue stratum, while these are DOI-bearing open-access articles from the deposit-based indexes that DO work here. A batch that wants measured ramp gradients rather than archival provenance should start here.', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:24', NULL);